long long min_cost(int N, int S, int T[], int C[])
{
    long long sumC[1001];
    long long dp[1001];
    sumC[N] = 0;
    dp[N] = 0;
    for (int i = N - 1; i >= 0; --i)
        sumC[i] = sumC[i + 1] + C[i];
    for (int i = N - 1; i >= 0; --i) {
        long long elapsed = S;
        long long best = 1LL << 62;
        for (int j = i; j < N; ++j) {
            elapsed += T[j];
            long long cost = elapsed * sumC[i] + dp[j + 1];
            if (cost < best) best = cost;
        }
        dp[i] = best;
    }
    return dp[0];
}
